fn class(status: Int) -> String {
    match status {
        _ where InRange(200, 299) => "success"   // ✗ the same test as `200..299`, and never exhaustive
        _ => "other"
    }
}

fn class(status: Int) -> String {
    match status {
        200..299 => "success"                  // ✓ counts towards exhaustiveness
        _ => "other"
    }
}
